// ============================================================
// EXTRACTOR AGENT
// Takes raw email text and extracts structured fields
// ============================================================

const emailText = $input.first().json.email_text || '';

// Validate input — return safe defaults if empty
if (!emailText || typeof emailText !== 'string') {
  return [{
    json: {
      error: 'No email text provided',
      sender: 'unknown',
      sender_domain: 'unknown',
      recipient: 'unknown',
      subject: 'unknown',
      body: '',
      urls: [],
      urgency_score: 0
    }
  }];
}

// ─── Extract sender ───
let sender = 'unknown';
const fromMatch = emailText.match(/From:\s*([^\n]+)/i);
if (fromMatch) {
  sender = fromMatch[1].trim();
}

// ─── Extract sender domain ───
let senderDomain = 'unknown';
if (sender.includes('@')) {
  senderDomain = sender.split('@').pop().toLowerCase().replace(/[>\s]/g, '');
}

// ─── Extract recipient ───
let recipient = 'unknown';
const toMatch = emailText.match(/To:\s*([^\n]+)/i);
if (toMatch) {
  recipient = toMatch[1].trim();
}

// ─── Extract subject ───
let subject = 'unknown';
const subjectMatch = emailText.match(/Subject:\s*([^\n]+)/i);
if (subjectMatch) {
  subject = subjectMatch[1].trim();
}

// ─── Extract body ───
let body = emailText;
if (emailText.includes('\n\n')) {
  body = emailText.split('\n\n').slice(1).join('\n\n');
}

// ─── Extract URLs ───
const urls = emailText.match(/https?:\/\/[^\s<>"']+/g) || [];

// ─── Urgency score ───
const urgencyKeywords = [
  'urgent', 'immediately', 'asap', 'critical', 'time-sensitive',
  'act now', 'expires', 'final notice', 'last chance'
];
const urgencyHits = urgencyKeywords.filter(kw =>
  emailText.toLowerCase().includes(kw)
).length;
const urgencyScore = Math.min(urgencyHits / 3, 1.0);

// ─── Return structured output ───
return [{
  json: {
    sender: sender,
    sender_domain: senderDomain,
    recipient: recipient,
    subject: subject,
    body: body,
    urls: urls,
    urgency_score: Math.round(urgencyScore * 100) / 100,
    email_text: emailText,
    extracted_at: new Date().toISOString(),
    url_count: urls.length
  }
}];
